// source.json                        // target.json
{                                     {
  "name": "Alice",                      "name": "Alice",
  "age": 31,                            "age": 31,
  "country": "USA",                     "country": "USA",
  "city": { "__tombstone__": true }     "city": { "__tombstone__": true }
